 if(!doc.querySelector('link[data-research-drawing-style]')){const link=doc.createElement('link');link.rel='stylesheet';link.href='/workspace/research-drawing-studio.css';link.dataset.researchDrawingStyle='';doc.head.append(link);}
 let live=true,ownerId=null,ownerConfirmed=false,invalidOwner=false,history=[],historyFilter='all',historyBusy=false,historyEpoch=0,previewEpoch=0,editRevision=0,savedRevision=0,form=initialForm(mode),jobState={},jobPanel=null,draftError='',storageKey='',preview=null,objectUrl='',previewBusy=false,pendingRecovery=null;
 const controllers=new Set(),fetchImpl=ctx.fetchImpl||win.fetch?.bind(win)||globalThis.fetch,objectUrls=win.URL?.createObjectURL?win.URL:globalThis.URL;
