 function panel(){if(jobPanel)return jobPanel;jobPanel=mountToolJobPanel({container:$('[data-rd-job]'),ctx:{...ctx,api:(path,data)=>request(path,data)},kind:'research',operation:'image',isCurrent:()=>current()&&!invalidOwner&&!hasDraftScope(),initialState:jobState,getSnapshot:()=>researchDrawingSnapshot(form,mode),onStateChange:value=>{if(hasDraftScope())throw Error('请先保存当前账户成果，再从科研工具页面生成图片。');jobState=value;if(!persisted())throw Error('浏览器未能保存任务草稿，已停止提交。请先复制描述并检查存储空间。');if(value.itemId)void refreshHistory();},onApply:async(output,item)=>{await displayImage(output,item);void refreshHistory();}});return jobPanel;}
