 function input(event){const target=event.target;if(target.hasAttribute('data-rd-type-search')){const value=target.value.trim().toLocaleLowerCase();container.querySelectorAll('[data-rd-figure]').forEach(button=>button.hidden=!!value&&!button.textContent.toLocaleLowerCase().includes(value));container.querySelectorAll('[data-rd-group]').forEach(group=>{group.hidden=![...group.querySelectorAll('[data-rd-figure]')].some(button=>!button.hidden);if(value&&!group.hidden)group.open=true;});return;}if(target.hasAttribute('data-rd-title'))form.title=target.value;else if(target.hasAttribute('data-rd-prompt'))form.prompt=target.value;else if(target.hasAttribute('data-rd-ratio'))form.aspectRatio=target.value;else if(target.hasAttribute('data-rd-palette'))form.palette=target.value;else return;changed();}
