 const ready=(async()=>{const revision=editRevision;try{await request('/auth/me');if(!current()||hasDraftScope())return;let raw;try{raw=win.localStorage.getItem(storageKey);if(raw!==null){if(raw.length>maxDraftBytes)throw Error('草稿超出范围');const saved=normalizeResearchDrawingDraft(JSON.parse(raw),mode);if(editRevision===revision){form=saved.form;jobState=saved.jobState;if(jobState.ownerId&&jobState.ownerId!==ownerId)jobState={};fillForm();}}}catch{draftError='本机草稿无法读取';status('本机绘图草稿无法读取，已保留原记录。请复制当前输入后重置本机草稿。',true);$('[data-rd-draft-recovery]').hidden=false;}if(editRevision!==revision&&!draftError)persisted();await refreshHistory();if(!current())return;const jobId=options.jobId||new URLSearchParams(win.location.hash.split('?')[1]||'').get('job');if(jobId&&idPattern.test(jobId))await openHistory(jobId);}catch(error){if(current()&&error.name!=='AbortError'&&!invalidOwner)status('账户连接暂不可用，输入仍保留。请稍后刷新记录或重新生成。',true);}})();
 return {ready,getSnapshot:()=>researchDrawingSnapshot(form,mode),refreshHistory,hasUnsaved:()=>!invalidOwner&&editRevision>savedRevision,saveDraft:()=>invalidOwner||editRevision===savedRevision||persisted(),dispose(){if(!live)return;if(!invalidOwner&&editRevision>savedRevision)persisted();live=false;historyEpoch++;previewEpoch++;jobPanel?.dispose();for(const c of controllers)c.abort();controllers.clear();if(objectUrl){objectUrls.revokeObjectURL(objectUrl);objectUrl='';}preview=null;history=[];container.removeEventListener('click',click);container.removeEventListener('input',input);container.removeEventListener('change',input);}};
